export const noteSlice = createSlice({
  name: '@@app/note',
  initialState,
  reducers: {
    addNote: (state, { payload }: PayloadAction<NoteItem>) => {
      state.notes = [...state.notes, payload]
    },
    updateNote: (state, { payload }: PayloadAction<NoteItem>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload.id ? { ...payload, lastUpdated: dayjs().format() } : note
      )
    },
    deleteNotes: (state, { payload }: PayloadAction<string[]>) => {
      state.notes = state.notes.filter((note) => !payload.includes(note.id))
    },
    assignFavoriteToNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload ? { ...note, favorite: true } : note
      )
    },
    unassignFavoriteFromNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload ? { ...note, favorite: false } : note
      )
    },
    assignTrashToNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload ? { ...note, trash: true } : note
      )
    },
    unassignTrashFromNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload ? { ...note, trash: false } : note
      )
    },
    assignCategoryToNotes: (state, { payload }: PayloadAction<{ categoryId: string; noteId: string }>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload.noteId ? { ...note, category: payload.categoryId } : note
      )
    },
    unassignCategoryFromNotes: (state, { payload }: PayloadAction<string>) => {
      state.notes = state.notes.map((note) =>
        note.id === payload ? { ...note, category: '' } : note
      )
    },
    updateActiveNote: (state, { payload }: PayloadAction<{ noteId: string; multiSelect: boolean }>) => {
      state.activeNoteId = payload.noteId
      state.selectedNotes = payload.multiSelect
        ? [...state.selectedNotes, payload.noteId]
        : [payload.noteId]
    },
    updateSelectedNotes: (state, { payload }: PayloadAction<{ noteId: string; multiSelect: boolean }>) => {
      state.selectedNotes = payload.multiSelect
        ? [...state.selectedNotes, payload.noteId]
        : [payload.noteId]
    },
    swapFolder: (state, { payload }: PayloadAction<{ folder: Folder; sortOrderKey: NotesSortKey }>) => {
      state.activeFolder = payload.folder
      state.activeCategoryId = ''
      state.activeNoteId = ''
      state.selectedNotes = []
    },
    setSearch: (state, { payload }: PayloadAction<string>) => {
      state.searchValue = payload
    },
  },
})
